import json
from pathlib import Path
p=Path(__file__).parent
base='https://developers.openai.com/api/docs/guides/'
urls={'best':base+'evaluation-best-practices','data':base+'evaluation-getting-started','grade':base+'graders','example':base+'evals'}
nodes=[]
def n(id,q,a,status='supported',ev=None):
    nodes.append(dict(id=id,question=q,answer=a,status=status,evidence=ev or []))
def e(src,loc,claim): return dict(url=urls[src],locator=loc,exact_claim=claim,basis='supplied verified packet paraphrase; not a quotation')
n('input_output','What does it mean to run a program on an input?','A program receives input, executes its instructions, and returns output.','assumed')
n('api','What does calling a model API do?','Your Python program sends input to a model service and receives a generated response.','assumed')
n('behavior','What behavior does an application eval measure?','It measures whether the application produces useful behavior for its intended task, rather than ranking a model’s general intelligence.',ev=[e('best','What are evals?; Types of evals','An application eval is a structured test of use-case behavior, distinct from a broad model benchmark.')])
n('variation','Why can a few good answers be misleading?','A model can return different answers to the same input; observing a few good outputs does not establish reliable behavior.',ev=[e('best','What are evals?','Generative responses can vary for the same input, making isolated successes insufficient evidence of reliability.')])
n('objective','How do you decide what counts as a successful support answer?','Specify the support task and observable success criteria using domain expertise. For a support assistant, plausible criteria include correct use of supplied policy, appropriate escalation, and useful communication; the exact criteria depend on the service.','partial',[e('best','Design your eval process','Start with the objective and measurements of success.'),e('data','Incorporate expert annotations','Domain expertise determines correct or useful behavior.')])
n('reference','What information establishes the intended answer for one case?','Human annotations can record the desired answer, an assessment of quality, a failure explanation, or a property such as tone. These annotations describe intended behavior, and a reference answer can be used in grading.',ev=[e('data','What annotation does; Annotation starting points; Incorporate expert annotations','Human annotations record desired behavior and informed judgments; references can be compared with generated answers.')])
n('case','What is a test case?','It is a recorded input together with the information needed to judge its output. For support, that may include the user’s request, relevant policy and conversation context, and expected behavior.','partial',[e('example','Create an eval for a task; Uploading test data','Each support-ticket classification item contains the ticket text and correct label.')])
n('dataset','Why collect more than one case?','A reusable collection lets you check multiple situations repeatedly. Cases should reflect expected usage and include failures and unusual inputs; logs, expert examples, and synthetic examples are possible sources.',ev=[e('best','Design your eval process','Choose relevant cases reflecting intended situations, including failures and unusual inputs.'),e('data','Create a dataset','A dataset provides multiple reusable examples.')])
n('grader','What is a grader?','A grader takes an output plus relevant case information and produces a judgment or score according to a chosen rule.',ev=[e('grade','Overview','A grader turns an output and relevant reference information into a judgment or score.')])
n('choice','How do you choose a grading rule?','Use exact comparison for one required precise form, programmed checks for computable requirements, and a model grader with explicit instructions for qualitative judgments. Similarity to a reference and satisfaction of a criterion measure different things.',ev=[e('grade','String check graders; Text similarity graders; Score model graders; Python graders','String checks, similarity checks, model grading, and Python checks assess distinct properties; exact comparison can penalize different wording with the same meaning.')])
n('calibration','Why check the grader against human judgments?','An automated score may fail to capture the intended quality. Compare automated assessments with informed human assessments before trusting the automated measure.',ev=[e('best','How to read evals; Evals tips','Human judgment checks whether the measure captures intended quality; automated assessments should be checked against human assessments.')])
n('run','What happens during an eval run?','Run a chosen application configuration on the recorded cases, retain its outputs, and apply the grading rules. Reusable criteria and data are distinct from a particular execution.',ev=[e('example','Creating an eval run; Analyze the results','A run supplies data and generation configuration, produces outputs and grading results, and is distinct from the reusable evaluation definition.')])
n('summary','What does an overall score tell you?','It summarizes the judgments on tested cases. For binary checks, a pass rate is the number of passing cases divided by the number tested. Report the counts and inspect failures; an overall rate can conceal differences between support situations.','partial',[e('best','How to read evals','A score is evidence about the measured behavior; unrepresentative data or unsuitable metrics can misrepresent production usefulness.')])
n('compare','How can you tell whether a change improved the assistant?','Rerun the same cases and grading criteria after changing the prompt, model, or other application component; compare outputs and failures as well as aggregate scores. Keep other settings fixed where feasible so the comparison is interpretable.','partial',[e('data','Add graders','Saved datasets and graders support repeated checks after prompt or model changes.'),e('best','Design your eval process','Repeated evaluation reveals regressions as well as gains.')])
n('limits','Why does a good eval score not guarantee production success?','It concerns only the tested situations and chosen measurements. Unrepresentative cases, an inaccurate grader, and response variation can limit what the score establishes. A small difference between runs may need more evidence.','partial',[e('best','How to read evals; Evals tips','A generic metric or unrepresentative dataset may reward behavior that is not useful in production.')])
n('improve','How do evaluation results lead to useful changes?','Inspect failed cases, revise the application in response to observed problems, rerun the evaluation, and add newly discovered real failures as reusable cases.',ev=[e('best','Design your eval process','Record real failures as test cases and repeat evaluations when application components change.'),e('example','Analyze the results','Analyze outputs and grading results before revising the prompt.')])
n('target','Why use evals, and how should a Python programmer start evaluating a customer-support assistant?','Evals turn selected examples and explicit success criteria into repeatable evidence about an application. Start with a narrow support task, record realistic and difficult cases with the context and expected behavior, choose and human-check graders, run a baseline, inspect scores and failures, and compare revisions on the same cases. Grow the suite from real failures. Treat the result as evidence with limits, not a guarantee.','partial',[])
edges=[]
def link(a,b,why): edges.append(dict(from_=a,to=b,why=why))
link('input_output','behavior','Without input/output behavior, the object being tested is undefined.')
link('api','variation','Without knowing that the API generates a response, variation has no identified source.')
link('behavior','objective','The intended application task is needed to define task-specific success.')
link('objective','reference','Without defined success, an annotation cannot express the intended judgment for a case.')
link('input_output','case','The reader must identify the input being recorded and the output later judged.')
link('reference','case','A runnable input alone lacks the case information needed to establish acceptable behavior.')
link('case','dataset','A reusable collection cannot be specified before its individual case is understood.')
link('reference','grader','The grader needs case-specific expected behavior against which it assesses the output.')
link('grader','choice','Without knowing a grader’s function, different checking rules have no common purpose.')
link('grader','calibration','Agreement with human judgments is a check on the automated grading judgment itself.')
link('objective','calibration','Human agreement matters only relative to what the application is intended to achieve.')
link('dataset','run','A run needs an identified collection of input cases.')
link('grader','run','An evaluation run requires a rule to convert outputs into assessments.')
link('api','run','Producing the application output requires the reader’s existing ability to call the model.')
link('run','summary','An aggregate score needs the individual assessments produced by a run.')
link('run','compare','Comparison needs two executions with specified configurations and shared evaluation conditions.')
link('summary','limits','To interpret an aggregate score’s limitations, the reader must know what it summarizes.')
link('variation','limits','Without response variation, a single execution’s uncertainty is unexplained.')
link('calibration','limits','Without grader checking, the possibility that a score measures the wrong quality is unexplained.')
link('dataset','limits','Coverage limitations concern which situations the collection includes.')
link('compare','improve','Without rerunning comparisons, a proposed fix has no evaluation evidence of improvement or regression.')
link('choice','target','Starting requires selecting checks suited to the support requirements.')
link('improve','target','The requested purpose includes using evaluation evidence to improve the assistant.')
link('limits','target','Explaining why to use evals requires stating what their evidence does and does not establish.')
link('objective','target','The startup procedure needs a concrete definition of acceptable support behavior.')
for x in edges:x['from']=x.pop('from_')
g=dict(schema_version=1,title='Prerequisites for evaluating a customer-support assistant',reader_assumptions=['Can write a small Python program using inputs and outputs.','Can call a model API.','No machine-learning or AI-engineering background.'],target_id='target',edge_semantics='A -> B: A is required to explain B; why describes the missing reasoning without A.',nodes=nodes,edges=edges,scope={'included':['application-level behavior','case data and grading','repeatable comparisons','initial customer-support workflow'],'excluded':['model training','general intelligence benchmarks','provider-specific platform setup','deployment approval thresholds','formal statistical significance testing'],'optional_examples':['Support ticket classification illustrates exact matching; open-ended support replies need additional criteria.']},revisions=[dict(round=0,kind='initial',description='Initial graph from supplied packet before supplemental research.',gaps=['Support-specific success criteria and conversation context','Score aggregation and grouped failures','Controlled comparisons and small-difference uncertainty','Evidence for proposed startup synthesis'])])
for name in ['dag.json','history/initial.json']:(p/name).write_text(json.dumps(g,indent=2)+'\n')
(p/'history/round-00.json').write_text(json.dumps(g['revisions'][0],indent=2)+'\n')
print(f'Saved initial graph: {len(nodes)} nodes, {len(edges)} edges')
